@property.ex:
class Doboz:
    @property
    def terfogat(self):
        return self.a * self.b * self.c

d = Doboz()
d.a, d.b, d.c = 2, 3, 4
print(d.terfogat)   # 24

@magassag.setter.ex:
class Ember:
    @property
    def kor(self):
        return self._kor

    @kor.setter
    def kor(self, ertek):
        if ertek < 0:
            raise ValueError("negatív kor")
        self._kor = ertek

e = Ember()
e.kor = 30
print(e.kor)   # 30
e.kor = -5     # ValueError: negatív kor

